'use strict';
// Presentation-only fixture data. No API, authentication, registration or organizer writes.
const root=document.getElementById('main');
const dialog=document.getElementById('detail-dialog');
const teamNames=['Garuda Nova','Vortex FC','North Force','Borneo Kings','Atlas District','Phoenix Core','South Rebels','Royal Rovers','Nusantara XI','Lunar United','East Wolves','Navy Athletic','Bandung City','Solo Strikers','Jakarta Elite','Falcon FC','Orbit FC','Pacific United','Medan Stars','Ace Rangers','Bali Phoenix','Delta Squad','Zenith FC','Echo Athletic','Surabaya Blue','West Knights','Unity Crew','Rising Star','Metro Lions','Tidal Force','Victory FC','Prime United'];
const teams=teamNames.map((name,id)=>({id,name,tag:name.split(' ').map(s=>s[0]).join('').slice(0,3),city:['Jakarta','Bandung','Surabaya','Samarinda','Yogyakarta','Malang','Solo','Bekasi'][id%8]}));
const phases={registration:{label:'PENDAFTARAN DIBUKA',tone:'cyan',date:'12 September 2026',count:24,action:'Daftarkan tim'},drawing:{label:'DRAWING RESMI TERBIT',tone:'violet',date:'17 September 2026',count:32,action:'Lihat jadwal'},live:{label:'SEDANG BERLANGSUNG',tone:'cyan',date:'19 September 2026',count:32,action:'Ikuti pertandingan'},finished:{label:'TURNAMEN SELESAI',tone:'cream',date:'20 September 2026',count:32,action:'Lihat hasil akhir'}};
const pageNames={home:'Beranda',event:'Ringkasan',participants:'Peserta',schedule:'Jadwal & Hasil',bracket:'Bracket',leaderboard:'Leaderboard',events:'Semua Event'};
let state={page:'home',phase:'live',query:'',teamStatus:'all',teamPage:1,metric:'goals',position:'all',playerTeam:'all',bracketView:'final',scheduleFilter:'all',eventFilter:'all'};
const paths={arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/><circle cx="9" cy="7" r="4"/>',bracket:'<path d="M3 3h5v6H3m5-3h5v12H8m-5-3h5v6H3m10-9h7"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18m-13 5h2m4 0h2"/>',trophy:'<path d="M8 3h8v5a4 4 0 0 1-8 0V3Zm0 1H4v3a4 4 0 0 0 5 4m7-7h4v3a4 4 0 0 1-5 4m-3 1v6m-4 3h8m-8 0v-3h8v3"/>',chart:'<path d="M4 20V10m8 10V4m8 16v-7M2 21h20"/>',play:'<path d="m9 5 11 7-11 7V5Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12v8h14v-8"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.arrow}</svg>`}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function href(page){return `#${page}/${state.phase}`}
function link(page,label,cls='text-link'){return `<a href="${href(page)}" data-page="${page}" class="${cls}">${label}</a>`}
function badge(label,tone='cyan'){return `<span class="badge ${tone}">${tone==='cyan'?'<span class="dot"></span>':''}${label}</span>`}
function phaseBadge(){return badge(phases[state.phase].label,phases[state.phase].tone)}
function crest(id,cls=''){const t=teams[id];return `<span class="crest ${id%3===1?'alt':id%3===2?'gold':''} ${cls}" aria-hidden="true">${t.tag}</span>`}
function head(num,title,page,label='Lihat lengkap'){return `<div class="section-head"><h2><span class="section-number">${num}</span>${title}</h2>${page?link(page,label+' '+icon('arrow')):''}</div>`}
function poster(){return `<div class="poster-stage" role="img" aria-label="Visual MFL Season 3 dengan dua karakter Flashpeak dan hadiah Rp400.000"><span class="poster-season" aria-hidden="true">03</span><div class="poster-lines"></div><div class="poster-top"><span>MIRACLE FOOTBALL LEAGUE</span><span>SEASON / 03</span></div><img class="first" src="character-art/roster/midfielder/Kelly.png" alt=""><img class="second" src="character-art/roster/striker/Rafael.png" alt=""><div class="poster-bottom"><p>THE FIELD. THE FIGHT. THE LEGACY.</p><strong>Rp400.000</strong><span>PRIZE POOL + GOLDEN TICKET TO PREMIER PEAK 2026</span></div></div>`}
function primaryAction(){if(state.phase==='registration')return '<button class="button primary" data-dialog="register">Daftarkan tim '+icon('arrow')+'</button>';return link(state.phase==='drawing'?'schedule':'event',phases[state.phase].action+' '+icon('arrow'),'button primary')}
function heroMatch(){if(state.phase==='registration')return `<div class="hero-match"><div class="hero-match-top"><b class="cyan">24 / 32 TIM TERDAFTAR</b><span class="muted">8 slot tersedia</span></div><p class="small-copy">Pendaftaran sampai 16 September · 23.59 WIB</p></div>`;if(state.phase==='drawing')return `<div class="hero-match"><div class="hero-match-top"><b class="violet">DRAWING SUDAH TERBIT</b><span class="muted">32 tim · 5 ronde</span></div><p class="small-copy">Kickoff 18 September · 18.00 WIB</p></div>`;return `<div class="hero-match"><div class="hero-match-top"><b class="${state.phase==='live'?'cyan':'cream'}">${state.phase==='live'?'● LIVE · QUARTERFINAL':'HASIL RESMI · GRAND FINAL'}</b><span class="muted">Best of ${state.phase==='live'?'3':'5'}</span></div><div class="hero-match-score"><span>${state.phase==='live'?'North Force':'Garuda Nova'}</span><b>${state.phase==='live'?'1 : 0':'3 : 1'}</b><span>${state.phase==='live'?'Borneo Kings':'Phoenix Core'}</span></div></div>`}
function homepage(){const p=phases[state.phase];return `<div class="wrap"><div class="home-intro"><span class="eyebrow">YOUR FRONT ROW TO THE GAME</span><span class="small-copy muted">${p.date} <span class="cyan">/ WIB</span></span></div><section class="home-hero"><div class="home-copy">${phaseBadge()}<h1>MIRACLE<br>FOOTBALL<br>LEAGUE <span>S3.</span></h1><p class="description">Satu lapangan. 32 tim. Satu cerita juara.<br>Ikuti setiap langkah menuju puncak.</p>${heroMatch()}<div class="actions">${link('event','Masuk event center '+icon('arrow'),'button primary')}${link('bracket','Lihat bracket','button')}</div><div class="home-metadata"><span><b>FLASHPEAK</b> · 5V5</span><span>18–20 SEP 2026</span><span><b>32</b> TIM</span></div></div>${poster()}</section><div class="pulse-strip"><div class="pulse-title"><span class="dot"></span> EVENT PULSE</div><div class="pulse-item">${state.phase==='live'?'Garuda Nova lolos ke semifinal':state.phase==='finished'?'Garuda Nova mengangkat trofi S3':state.phase==='drawing'?'Bracket resmi sudah bisa dilihat':'24 tim siap mengambil panggung'}<p>${state.phase==='live'?'Menang 2–1 atas Vortex FC · 19.05 WIB':state.phase==='finished'?'Menang 3–1 atas Phoenix Core · Final':state.phase==='drawing'?'Diterbitkan organizer · 17 Sep, 20.00 WIB':'Pendaftaran dibuka sampai 16 September'}</p></div><div class="pulse-item">${state.phase==='live'?'Berikutnya: Atlas District vs Phoenix Core':state.phase==='finished'?'Statistik akhir dan penghargaan terbit':state.phase==='drawing'?'Pertandingan pertama besok, 18.00 WIB':'Jalur menuju champion sudah terbuka'}<p>${state.phase==='live'?'Quarterfinal · Jadwal diperbarui ke 20.45 WIB':state.phase==='finished'?'Buka event center untuk recap lengkap':state.phase==='drawing'?'Cek jadwal tim favoritmu':'Lihat struktur bracket · Drawing oleh organizer'}</p></div></div><section class="section">${head('01','Di dalam arena','event','Jelajahi event')}<div class="quick-grid">${[['participants','users','Peserta','Kenali tim dan rosternya'],['schedule','calendar','Jadwal & Hasil','Jangan lewatkan pertandingan'],['bracket','bracket','Road to Champion','Ikuti perjalanan menuju final'],['leaderboard','chart','Leaderboard','Pemain di balik setiap kemenangan']].map(([page,i,title,desc])=>`<a href="${href(page)}" data-page="${page}" class="quick-card">${icon(i)}<span class="arrow">↗</span><h3>${title}</h3><p>${desc}</p></a>`).join('')}</div></section><section class="section two-col"><div>${head('02',state.phase==='registration'?'Panggung berikutnya':state.phase==='finished'?'Momen penentu':'Sorotan pertandingan')}${state.phase==='registration'?registrationCard():state.phase==='drawing'?scheduleTeaser():liveCard()}</div><aside class="stack">${organizerCard()}</aside></section><div class="history-strip"><div class="history-symbol">${icon('trophy')}</div><div><div class="eyebrow cream">SEBELUMNYA DI MIRACLE</div><h3>MFL Season 2 · The previous chapter</h3><p>Kompetisi berakhir. Ceritanya tetap tersimpan.</p></div><button class="button small" data-dialog="archive">Buka arsip S2 ${icon('arrow')}</button></div></div>`}
const eventCatalog=[
  {id:'mfl-s2',title:'Miracle Football League S2',game:'Flashpeak · 5v5',date:'24–29 Agustus 2026',status:'Selesai',kind:'finished',issue:'02',theme:'violet',note:'Champion: Royal Rovers'},
  {id:'kuroko-summer',title:'Kuroko Street Rival Summer Cup',game:'Kuroko no Basket · 3v3',date:'8–10 Agustus 2026',status:'Selesai',kind:'finished',issue:'08',theme:'cream',note:'8 tim · Hasil resmi'},
  {id:'mfl-rookie',title:'MFL Rookie Cup',game:'Flashpeak · 5v5',date:'4–5 Oktober 2026',status:'Akan datang',kind:'upcoming',issue:'R1',theme:'cyan',note:'Registrasi dibuka 24 September'}
];
function currentEventItem(){const p=phases[state.phase];return {id:'mfl-s3',title:'Miracle Football League S3',game:'Flashpeak · 5v5',date:'18–20 September 2026',status:p.label,kind:state.phase==='finished'?'finished':'current',issue:'03',theme:'cyan',note:state.phase==='live'?'Quarterfinal berlangsung':state.phase==='registration'?'24 / 32 tim terdaftar':state.phase==='drawing'?'Drawing resmi sudah terbit':'Champion: Garuda Nova',current:true}}
function eventCard(e){const inner=`<span class="event-card-art ${e.theme}"><b aria-hidden="true">${e.issue}</b><span>${e.game}</span><strong>${e.title}</strong></span><span class="event-card-copy">${badge(e.status,e.current?phases[state.phase].tone:e.kind==='upcoming'?'violet':e.theme)}<strong>${e.title}</strong><span>${e.date}</span><small>${e.note}</small><i>${e.current?'Masuk event center':'Lihat event'} ↗</i></span>`;return e.current?`<a href="${href('event')}" data-page="event" class="event-list-card">${inner}</a>`:`<button class="event-list-card" data-other-event="${e.id}">${inner}</button>`}
function otherEventSection(){return `<section class="section">${head('02','Event lainnya','events','Semua event')}<p class="section-intro">Event utama tetap menjadi panggung terdepan. Event yang akan datang dan arsip kompetisi tetap mudah ditemukan.</p><div class="event-list-grid">${eventCatalog.map(eventCard).join('')}</div></section>`}
function eventsPage(){return `<div class="wrap"><div class="breadcrumb">${link('home','Beranda','')}<span>/</span><span>Semua event</span></div><div class="page-heading"><div><div class="eyebrow cyan">MIRACLE / EVENT ARCHIVE</div><h1>Satu panggung utama.<br>Semua cerita tetap hidup.</h1><p>Temukan event yang sedang menjadi pusat perhatian, agenda berikutnya, dan hasil kompetisi sebelumnya.</p></div><div class="stat-inline"><div><strong>01</strong><span>Event utama</span></div><div><strong>03</strong><span>Event lain</span></div></div></div><div class="directory-toolbar"><div class="segmented" role="group" aria-label="Filter event"><button data-event-filter="all" class="${state.eventFilter==='all'?'active':''}" aria-pressed="${state.eventFilter==='all'}">Semua</button><button data-event-filter="current" class="${state.eventFilter==='current'?'active':''}" aria-pressed="${state.eventFilter==='current'}">Event utama</button><button data-event-filter="upcoming" class="${state.eventFilter==='upcoming'?'active':''}" aria-pressed="${state.eventFilter==='upcoming'}">Akan datang</button><button data-event-filter="finished" class="${state.eventFilter==='finished'?'active':''}" aria-pressed="${state.eventFilter==='finished'}">Selesai</button></div><span class="small-copy muted">Diurutkan berdasarkan waktu terdekat</span></div><div id="event-results" class="event-list-grid directory-grid"></div><div class="notice" style="margin-top:26px"><b>Mengapa hanya satu event aktif?</b><p>Miracle memberi ruang terbesar kepada kompetisi yang sedang berjalan. Event lain tetap tersedia sebagai agenda dan arsip, tanpa membuat perhatian penonton terpecah.</p></div></div>`}
function renderEvents(){const all=[currentEventItem(),...eventCatalog];const visible=state.eventFilter==='all'?all:all.filter(e=>e.kind===state.eventFilter);document.getElementById('event-results').innerHTML=visible.length?visible.map(eventCard).join(''):'<div class="empty-state" style="grid-column:1/-1"><h3>Belum ada event di kategori ini.</h3><p style="margin-top:10px">Coba kategori lain untuk melihat event Miracle.</p></div>'}
function showOtherEvent(id){const e=eventCatalog.find(item=>item.id===id);if(!e)return;showDialog(`<div class="eyebrow ${e.theme}">${e.game}</div><h2>${e.title}</h2><p>${e.date} · ${e.note}</p>${badge(e.status,e.kind==='upcoming'?'violet':e.theme)}<div class="notice" style="margin-top:20px"><b>${e.kind==='upcoming'?'Event akan datang':'Arsip event'}</b><p>${e.kind==='upcoming'?'Halaman event lengkap akan tersedia saat organizer mempublikasikannya.':'Hasil, bracket, peserta, dan leaderboard event ini tetap tersedia pada URL permanennya.'}</p></div>`)}
function eventNav(){return `<nav class="event-nav" aria-label="Navigasi event">${['event','participants','schedule','bracket','leaderboard'].map(page=>`<a href="${href(page)}" data-page="${page}" class="${state.page===page?'active':''}" ${state.page===page?'aria-current="page"':''}>${pageNames[page]}</a>`).join('')}<button class="icon-button" data-dialog="share" aria-label="Bagikan event">${icon('share')}</button></nav>`}
function eventShell(body,full=false){return `<div class="wrap"><div class="breadcrumb">${link('home','Beranda','')}<span>/</span>${link('event','MFL Season 3','')}<span>/</span><span>${pageNames[state.page]}</span></div>${full?`<section class="event-hero"><div class="event-hero-top"><div class="event-identity">${phaseBadge()}<h1>Miracle Football<br>League S3</h1><p>32 tim bertarung untuk satu gelar dan Golden Ticket menuju Premier Peak 2026. Ini perjalanan mereka.</p><div class="organizer-line">Diselenggarakan oleh <strong>Miracle League</strong><span class="verified">✓ Terverifikasi</span></div></div>${poster()}</div><div class="event-facts"><div class="fact"><span>Game & mode</span><b>Flashpeak · 5v5</b></div><div class="fact"><span>Match day</span><b>18–20 Sep 2026 · WIB</b></div><div class="fact"><span>Prize pool</span><b>Rp400.000 + Golden Ticket</b></div><div class="fact"><span>Format</span><b>32 tim · Single Elimination</b></div>${state.phase==='registration'?primaryAction():`<button class="button" data-dialog="share">Bagikan ${icon('share')}</button>`}</div></section>`:`<div class="event-compact"><span class="event-monogram">MFL</span><div><div class="eyebrow muted">FLASHPEAK · SINGLE ELIMINATION</div><h2>${link('event','Miracle Football League S3','')}</h2></div>${phaseBadge()}</div>`}${eventNav()}${body}</div>`}
function registrationCard(){return `<section class="panel panel-pad reg-copy"><div class="eyebrow cyan">PENDAFTARAN TIM / 11–16 SEPTEMBER</div><h2>Tempatmu di kompetisi<br>dimulai di sini.</h2><p>Siapkan tim terbaikmu. Delapan slot terakhir menunggu sebelum perjalanan menuju champion dimulai.</p><div class="info-box"><div><b>24 <span>/ 32 tim</span></b><span>Peserta terdaftar</span></div><div><b>Rp20.000</b><span>Biaya per tim</span></div></div><div class="progress"><span style="width:75%"></span></div><div class="actions">${primaryAction()}${link('participants','Lihat peserta '+icon('arrow'))}</div><p class="info-note" style="margin:15px 0 0">5 pemain inti + maks. 2 cadangan · Verifikasi oleh organizer</p></section>`}
function organizerCard(){return `<section class="panel"><div class="panel-title"><h3>Di balik kompetisi</h3>${icon('shield')}</div><div class="panel-pad"><div class="org-row"><div class="org-logo"><img src="logo/miracle-symbol.svg" alt=""></div><div><h3>Miracle League</h3><p class="verified">✓ Organizer terverifikasi</p></div></div><p class="small-copy">Kompetisi Flashpeak yang tumbuh bersama komunitas. Dari kickoff sampai selebrasi terakhir.</p><div class="actions" style="margin-top:17px"><button class="button small" data-dialog="contact">Hubungi organizer ${icon('arrow')}</button></div></div></section>`}
function announcements(){return `<section class="panel"><div class="panel-title"><h3>Pengumuman resmi</h3><span class="badge">ORGANIZER</span></div><ul class="updates">${state.phase==='live'?'<li><time>19 SEP · 19.30 WIB</time><p>Atlas District vs Phoenix Core dimulai 20.45 WIB, mundur 15 menit.</p></li><li><time>19 SEP · 19.05 WIB</time><p>Garuda Nova menjadi tim pertama yang lolos ke semifinal.</p></li>':state.phase==='finished'?'<li><time>20 SEP · 22.15 WIB</time><p>Hasil akhir dan statistik resmi telah diterbitkan.</p></li><li><time>20 SEP · 22.00 WIB</time><p>Selamat kepada Garuda Nova, champion MFL S3.</p></li>':'<li><time>12 SEP · 12.00 WIB</time><p>Technical meeting pada 17 September, 19.00 WIB.</p></li><li><time>11 SEP · 10.00 WIB</time><p>Pendaftaran dibuka. Siapkan roster dan bukti pembayaran tim.</p></li>'}</ul></section>`}
function liveCard(){const done=state.phase==='finished';const a=done?0:2,b=done?5:3;return `<section class="panel live-card"><div class="panel-title">${badge(done?'HASIL RESMI':'● LIVE SEKARANG',done?'cream':'cyan')}<span class="small-copy muted">${done?'Grand Final · BO5':'Quarterfinal 2 · BO3'}</span></div><div class="scoreboard"><div>${crest(a)}<h3>${teams[a].name}</h3><p>${teams[a].city}</p></div><div><div class="score">${done?'3 : 1':'1 : 0'}</div><div class="score-meta">${done?'SERIES SELESAI':'GAME 2 BERJALAN'}</div><div class="score-games"><i class="won"></i><i class="${done?'won':'current'}"></i><i class="${done?'won':''}"></i></div></div><div>${crest(b)}<h3>${teams[b].name}</h3><p>${teams[b].city}</p></div></div><div class="match-footer"><div><b class="small-copy">${done?'Champion: Garuda Nova':'Panggung utama · 19.30 WIB'}</b><p>${done?'20 September 2026 · Hasil dikonfirmasi organizer':'Skor series diperbarui setelah hasil resmi'}</p></div><button class="button ${done?'':'cyan-button'}" ${done?'data-match="f-0"':'data-dialog="stream"'}>${icon(done?'chart':'play')}${done?'Detail final':'Tonton siaran'}</button></div></section>`}
function scheduleTeaser(){const reg=state.phase==='registration';return `<section class="panel"><div class="panel-title"><h3>${reg?'Agenda kompetisi':state.phase==='finished'?'Hasil penentuan':'Berikutnya di lapangan'}</h3>${link('schedule','Semua '+icon('arrow'))}</div><div class="upcoming-list">${(reg?[['17 SEP','Technical meeting','19.00 WIB · Online'],['18 SEP','Kickoff & babak 32 besar','18.00 WIB · Panggung utama'],['20 SEP','Semifinal & grand final','18.00 WIB · Hari penentuan']]:state.phase==='finished'?[['3 : 1','Garuda Nova vs Phoenix Core','Grand Final · Hasil resmi'],['2 : 1','North Force vs South Rebels','Perebutan tempat ketiga · Hasil resmi']]:state.phase==='drawing'?[['18.00','Garuda Nova vs Orbit FC','18 Sep · Babak 32 besar'],['18.30','Nusantara XI vs Surabaya Blue','18 Sep · Babak 32 besar']]:[['20.45','Atlas District vs Phoenix Core','Quarterfinal 3 · BO3'],['21.30','South Rebels vs Royal Rovers','Quarterfinal 4 · BO3']]).map(([time,title,note])=>`<div class="fixture"><div class="small-copy cyan">${time}</div><div><div class="fixture-team">${title}</div><p>${note}</p></div>${icon('arrow')}</div>`).join('')}</div></section>`}
function bracketPreview(){const reg=state.phase==='registration';return `<section class="section">${head('02','Road to Champion','bracket','Buka bracket')}<div class="panel panel-pad"><div class="section-head" style="margin-bottom:12px"><div><div class="eyebrow ${reg?'violet':'cyan'}">${reg?'PRATINJAU FORMAT':'BRACKET RESMI'}</div><p>${reg?'Posisi tim ditentukan organizer setelah registrasi ditutup.':'Ikuti jalur delapan tim terakhir menuju trofi.'}</p></div>${icon('bracket')}</div>${reg?'<div class="road-map"><span>32 tim</span>→<span>16 besar</span>→<span>Quarterfinal</span>→<span>Semifinal</span>→<b>Champion</b></div>':''}<div class="bracket-scroll" style="margin-top:18px;max-height:330px" tabindex="0" role="region" aria-label="Pratinjau bracket, geser untuk menjelajah">${boardHtml('preview')}</div><p class="info-note">${reg?'Semua slot tetap TBD sampai organizer mempublikasikan drawing resmi.':'Skor mengikuti hasil resmi. Buka bracket untuk melihat seluruh ronde.'}</p></div></section>`}
const individualAwards=[
  {id:'mvp',initials:'RF',title:'MVP of Tournament',player:'Rift',team:'Garuda Nova',proof:'53 save · 8 game · penentu perjalanan champion'},
  {id:'scorer',initials:'VT',title:'Top Scorer',player:'Volt',team:'Garuda Nova',proof:'26 gol'},
  {id:'defender',initials:'KZ',title:'Top Defender',player:'Kaze',team:'Garuda Nova',proof:'82% duel bertahan dimenangkan'},
  {id:'assist',initials:'AR',title:'Top Assist',player:'Aero',team:'Garuda Nova',proof:'20 assist'}
];
function awardsSection(){return `<section class="section awards-section"><div class="panel"><div class="panel-title awards-heading"><div><h3>Penghargaan individual</h3><p>Pemenang berdasarkan statistik resmi dan keputusan organizer.</p></div>${link('leaderboard','Lihat leaderboard akhir','button small')}</div><div class="award-grid">${individualAwards.map(award=>`<article class="award-card"><span class="award-avatar">${award.initials}</span><div><b>${award.title}</b><span>${award.player} · ${award.team}</span><small>${award.proof}</small></div><button class="award-certificate-link" data-award-certificate="${award.id}">Buka sertifikat <span aria-hidden="true">↗</span></button></article>`).join('')}</div></div></section>`}
function showAwardCertificate(id){const award=individualAwards.find(item=>item.id===id);if(!award)return;showDialog(`<div class="eyebrow cream">SERTIFIKAT PENGHARGAAN · MFL S3</div><h2>${award.title}</h2><p>Diberikan kepada ${award.player} · ${award.team}. ${award.proof}.</p><div class="certificate-mini"><span class="award-avatar">${award.initials}</span><div><div class="eyebrow cream">MIRACLE FOOTBALL LEAGUE S3</div><h2 style="color:var(--cream)">${award.title.toUpperCase()}</h2><h3>${award.player.toUpperCase()}</h3><p>${award.team} · Terbit 20 September 2026</p></div></div><p class="info-note">Certificate ID: MFL-S3-${award.id.toUpperCase()} · Pada produk, tautan membuka sertifikat publik yang dapat diverifikasi.</p>`)}
function leaderboardPreview(){if(state.phase==='finished')return awardsSection();const ready=state.phase==='live';return `<section class="section">${head('03','Pemain dalam sorotan','leaderboard','Leaderboard')}<div class="panel">${ready?statPlayers().sort((a,b)=>b.goals-a.goals||b.matches-a.matches||a.name.localeCompare(b.name)).slice(0,3).map((p,i)=>`<div class="roster-row" style="padding:18px 24px"><div class="table-person"><span class="table-rank ${i===0?'cream':''}">0${i+1}</span>${crest(p.team,'mini')}<div><b>${p.name}</b><small>${teams[p.team].name}</small></div></div><b class="cyan">${p.goals} <small class="muted">gol</small></b></div>`).join(''):`<div class="empty-state" style="border:0;padding:30px"><h3>Statistik menunggu kickoff.</h3><p style="margin-top:10px">Peringkat terisi setelah statistik pertandingan ditinjau dan diterbitkan organizer.</p></div>`}</div></section>`}
function champion(){return `<div class="champion-banner"><div><div class="eyebrow cream">OFFICIAL CHAMPION / MFL SEASON 3</div><h2>Garuda Nova.<br>Built for this moment.</h2><p>Menutup perjalanan dengan kemenangan 3–1 di Grand Final.</p></div>${crest(0,'gold')}</div><div class="podium-row">${[[0,'01','CHAMPION'],[5,'02','RUNNER-UP'],[2,'03','THIRD PLACE']].map(([id,n,title])=>`<div class="podium-card ${n==='01'?'first':''}"><div class="eyebrow ${n==='01'?'cream':'muted'}" style="margin-bottom:15px">${n} / ${title}</div>${crest(id)}<b>${teams[id].name}</b></div>`).join('')}</div>`}
function eventPage(){return eventShell(`<div class="two-col"><div>${state.phase==='registration'?registrationCard():state.phase==='drawing'?`<section class="panel panel-pad"><div class="eyebrow violet">DRAWING DIKUNCI & DIPUBLIKASIKAN</div><h2 style="margin:12px 0">Tim sudah mendapat tempat.<br>Kickoff tinggal selangkah.</h2><p class="small-copy">32 tim · 17 September, 20.00 WIB · Oleh Miracle League</p><div class="actions" style="margin-top:22px">${link('bracket','Lihat bracket resmi '+icon('arrow'),'button primary')}${link('schedule','Jadwal pertandingan','button')}</div></section>`:state.phase==='finished'?champion():liveCard()}${state.phase==='live'?'<div class="notice" style="margin-top:16px"><b>Perubahan jadwal · Quarterfinal 3</b><p>Atlas District vs Phoenix Core dimulai 20.45 WIB. Jadwal di halaman ini sudah diperbarui.</p></div>':''}<div class="content-bottom">${scheduleTeaser()}</div>${bracketPreview()}${leaderboardPreview()}${state.phase==='finished'?`<section class="section">${head('04','Jejak kemenangan')}<button class="certificate-mini" style="width:100%;text-align:left" data-dialog="certificate">${icon('trophy')}<div><h3>Sertifikat Champion · Garuda Nova</h3><p>Terbit 20 September 2026 · Lihat pratinjau sertifikat</p></div><span style="margin-left:auto">↗</span></button></section>`:''}<section class="section panel panel-pad rules-details"><details><summary><b>Peraturan & informasi event</b><span>+</span></summary><p>Single Elimination, 32 tim, 5 pemain inti dan maksimal 2 cadangan. Babak 32 besar dan 16 besar memakai BO1, quarterfinal dan semifinal BO3, final BO5. Pertandingan perebutan tempat ketiga memakai BO3.</p><p>Technical meeting: 17 September 2026, 19.00 WIB. Seluruh jadwal menggunakan WIB. Keputusan drawing dan publikasi hasil ada pada organizer.</p></details></section></div><aside class="stack">${organizerCard()}${announcements()}<section class="panel panel-pad"><div class="eyebrow muted">EVENT ESSENTIALS</div><ul class="rule-list"><li><b>01</b><span>18–20 September 2026</span></li><li><b>02</b><span>Online · Server Indonesia</span></li><li><b>03</b><span>32 tim · Single Elimination</span></li><li><b>04</b><span>Golden Ticket untuk 2 finalis</span></li></ul></section></aside></div>`,true)}
function teamStatus(t){if(state.phase==='registration'||state.phase==='drawing')return {label:'Terdaftar',kind:'registered',tone:'cyan'};if(state.phase==='finished')return t.id===0?{label:'Champion',kind:'active',tone:'cream'}:t.id===5?{label:'Runner-up',kind:'active',tone:'violet'}:t.id===2?{label:'Peringkat 3',kind:'active',tone:'violet'}:{label:'Selesai',kind:'out',tone:''};if(t.id===0)return {label:'Semifinal',kind:'active',tone:'violet'};if(t.id===2||t.id===3)return {label:'Live',kind:'active',tone:'cyan'};return [4,5,6,7].includes(t.id)?{label:'Quarterfinal',kind:'active',tone:'violet'}:{label:'Tereliminasi',kind:'out',tone:''}}
function participantsPage(){return eventShell(`<div class="page-heading"><div><div class="eyebrow cyan">THE TEAMS / MFL S3</div><h1>Kenali para penantang.</h1><p>Tim, roster, dan perjalanan mereka. Urutan daftar ini tidak menentukan posisi bracket.</p></div><div class="stat-inline"><div><strong>${phases[state.phase].count}<span> / 32</span></strong><span>Tim terdaftar</span></div><div><strong>${phases[state.phase].count*5}</strong><span>Pemain inti</span></div></div></div><div class="toolbar"><div class="field search-field"><label for="team-search">Cari tim atau pemain</label><input id="team-search" type="search" placeholder="Nama tim, tag, atau nickname pemain…" value="${esc(state.query)}"></div><div class="field"><label for="team-status">Status tim</label><select id="team-status"><option value="all">Semua tim</option>${['live','finished'].includes(state.phase)?'<option value="active">Masih bertanding / podium</option><option value="out">Tereliminasi / selesai</option>':''}</select></div><span class="small-copy muted" style="padding-bottom:12px">Urutan A–Z</span></div><div id="team-results"></div><p class="info-note">Hanya peserta terdaftar yang ditampilkan. Data kontak captain dan bukti pembayaran bersifat privat.</p>`)}
function roster(t){const nick=['Volt','Aero','Kaze','Nox','Rift'];return Array.from({length:5},(_,i)=>({name:(players.filter(p=>p.team===t.id&&p.position===['Striker','Midfielder','Defender','Defender','Goalkeeper'][i])[i===3?1:0]?.name)||(t.id===0?nick[i]:`${t.tag}.${nick[i]}`),role:['Striker','Midfielder','Defender','Defender','Goalkeeper'][i],captain:i===0}))}
function renderTeams(){const count=phases[state.phase].count;const found=teams.slice(0,count).filter(t=>(t.name+' '+t.tag+' '+roster(t).map(p=>p.name).join(' ')).toLowerCase().includes(state.query.toLowerCase())&&(state.teamStatus==='all'||teamStatus(t).kind===state.teamStatus)).sort((a,b)=>a.name.localeCompare(b.name));const pages=Math.max(1,Math.ceil(found.length/12));state.teamPage=Math.min(state.teamPage,pages);const slice=found.slice((state.teamPage-1)*12,state.teamPage*12);document.getElementById('team-results').innerHTML=slice.length?`<div class="team-grid">${slice.map(t=>{const status=teamStatus(t);return `<button class="team-card" data-team="${t.id}"><span class="team-card-top">${crest(t.id)}${badge(status.label,status.tone)}</span><h3>${t.name}</h3><p>${t.city} · ${t.tag}</p><span class="team-card-foot"><span>5 pemain inti</span><span class="cyan">Lihat roster ↗</span></span></button>`}).join('')}</div><div class="list-bottom"><span>${(state.teamPage-1)*12+1}–${Math.min(state.teamPage*12,found.length)} dari ${found.length} tim</span><div class="pagination" aria-label="Halaman peserta">${Array.from({length:pages},(_,i)=>`<button data-team-page="${i+1}" class="${state.teamPage===i+1?'active':''}" ${state.teamPage===i+1?'aria-current="page"':''}>${i+1}</button>`).join('')}</div></div>`:'<div class="empty-state"><h3>Tim tidak ditemukan.</h3><p style="margin-top:10px">Coba nama lain atau ubah filter status.</p></div>';document.getElementById('team-status').value=state.teamStatus}
function matchData(){const reg=state.phase==='registration',drawing=state.phase==='drawing',done=state.phase==='finished';const early=!reg&&!drawing;const m=(id,a,b,sa,sb,status,label,date,bo)=>({id,a:reg?null:a,b:reg?null:b,sa:!reg&&(status==='done'||status==='live')?sa:null,sb:!reg&&(status==='done'||status==='live')?sb:null,status:reg?'preview':status,label,date,bo});const firstOrder=[0,8,1,9,2,10,3,11,4,12,5,13,6,14,7,15];const r32=firstOrder.map((id,i)=>m('r32-'+i,id,id+16,1,0,early?'done':'scheduled','32 besar',`18 Sep · ${18+Math.floor(i/4)}.${String(i%4*15).padStart(2,'0')}`,1));const r16=Array.from({length:8},(_,i)=>m('r16-'+i,i,i+8,1,0,early?'done':'scheduled','16 besar',`19 Sep · ${12+Math.floor(i/2)}.${i%2?'30':'00'}`,1));const qf=[[0,1,2,1],[2,3,2,0],[4,5,1,2],[6,7,2,0]].map(([a,b,sa,sb],i)=>m('qf-'+i,a,b,done||i===0?sa:i===1?1:sa,sb,done?'done':drawing?'scheduled':i===0?'done':i===1?'live':'scheduled','Quarterfinal',`19 Sep · ${['18.00','19.30','20.45','21.30'][i]}`,3));const sf=[[0,2,2,1],[5,6,2,0]].map(([a,b,sa,sb],i)=>m('sf-'+i,done?a:i===0&&early?0:null,done?b:null,sa,sb,done?'done':'scheduled','Semifinal',`20 Sep · ${18+i}.00`,3));const final=[m('f-0',done?0:null,done?5:null,3,1,done?'done':'scheduled','Grand Final','20 Sep · 21.00',5)];const third=m('third-0',done?2:null,done?6:null,2,1,done?'done':'scheduled','Perebutan tempat ketiga','20 Sep · 20.00',3);return {r32,r16,qf,sf,final,third}}
function matchHtml(m){const isPreview=state.phase==='registration',winner=m.sa>m.sb?m.a:m.b;const side=(id,score)=>`<div class="bracket-team ${m.status==='done'&&id===winner?'winner':''}"><span class="team-dot">${id===null?'—':teams[id].tag}</span><span>${id===null?'TBD':teams[id].name}</span><b>${score??'—'}</b></div>`;return `<button class="bracket-match ${m.status==='live'?'current-match':m.status==='done'?'completed':''}" data-match="${m.id}" aria-label="${m.label}: ${m.a===null?'TBD':teams[m.a].name} versus ${m.b===null?'TBD':teams[m.b].name}"><span class="match-meta"><span>${isPreview?'PRATINJAU':m.status==='live'?'● LIVE':m.status==='done'?'SELESAI':m.date} ${!isPreview&&m.status==='scheduled'?'WIB':''}</span><span>BO${m.bo}</span></span>${side(m.a,m.sa)}${side(m.b,m.sb)}</button>`}
function boardHtml(view){const d=matchData();let rounds;if(view==='all')rounds=[['32 besar',d.r32,1],['16 besar',d.r16,1],['Quarterfinal',d.qf,3],['Semifinal',d.sf,3],['Grand Final',d.final,5]];else if(view==='a')rounds=[['32 besar · Bagian A',d.r32.slice(0,4),1],['16 besar',d.r16.slice(0,2),1],['Quarterfinal 1',d.qf.slice(0,1),3]];else if(view==='b')rounds=[['32 besar · Bagian B',d.r32.slice(4,8),1],['16 besar',d.r16.slice(2,4),1],['Quarterfinal 2',d.qf.slice(1,2),3]];else if(view==='c')rounds=[['32 besar · Bagian C',d.r32.slice(8,12),1],['16 besar',d.r16.slice(4,6),1],['Quarterfinal 3',d.qf.slice(2,3),3]];else if(view==='d')rounds=[['32 besar · Bagian D',d.r32.slice(12,16),1],['16 besar',d.r16.slice(6,8),1],['Quarterfinal 4',d.qf.slice(3,4),3]];else rounds=[['Quarterfinal',d.qf,3],['Semifinal',d.sf,3],['Grand Final',d.final,5]];return `<div class="bracket-board">${rounds.map(([title,list,bo])=>`<div class="round"><div class="round-title">${title}<span>BO${bo}</span></div><div class="round-matches">${list.map(matchHtml).join('')}</div></div>`).join('')}</div>`}
function drawConnectors(){document.querySelectorAll('.bracket-board').forEach(board=>{board.querySelectorAll('.connector').forEach(el=>el.remove());const rounds=[...board.querySelectorAll('.round')];const box=board.getBoundingClientRect();rounds.slice(0,-1).forEach(round=>{const matches=[...round.querySelectorAll('.bracket-match')];for(let i=0;i<matches.length-1;i+=2){const a=matches[i].getBoundingClientRect(),b=matches[i+1].getBoundingClientRect();const conn=document.createElement('span');conn.className='connector';conn.setAttribute('aria-hidden','true');conn.style.cssText=`left:${a.right-box.left+19}px;top:${a.top-box.top+a.height/2}px;height:${b.top+b.height/2-a.top-a.height/2}px`;board.append(conn)}})})}
function bracketPage(){const reg=state.phase==='registration';return eventShell(`<div class="page-heading"><div><div class="eyebrow cyan">THE ROAD / MFL S3</div><h1>Road to Champion.</h1><p>${reg?'Lihat bentuk kompetisinya sejak awal. Semua slot memakai TBD sampai organizer menerbitkan drawing resmi.':'Dari 32 penantang hingga satu champion. Klik pertandingan untuk melihat detail series.'}</p></div><div class="stat-inline"><div><strong>32</strong><span>Tim</span></div><div><strong>5</strong><span>Ronde menuju juara</span></div></div></div><div class="notice" style="border-color:var(--${reg?'violet':'cyan'})"><b>${reg?'Pratinjau format · belum ada penempatan tim':'Bracket resmi · Drawing v1'}</b><p>${reg?'Organizer menetapkan dan mempublikasikan drawing setelah registrasi ditutup. Urutan pendaftaran tidak menentukan seed.':'Dipublikasikan oleh Miracle League · 17 September 2026, 20.00 WIB. Hasil drawing yang dipublikasikan menjadi acuan pertandingan.'}</p></div><div class="step-rail"><span class="${reg?'active':''}">01 · Pratinjau format</span><span class="${state.phase==='drawing'?'active':''}">02 · Drawing resmi</span><span class="${state.phase==='live'?'active':''}">03 · Pertandingan</span><span class="${state.phase==='finished'?'active':''}">04 · Hasil akhir</span></div><div class="bracket-toolbar"><div class="field"><label for="bracket-stage">Area bracket</label><select id="bracket-stage"><option value="final">Final stage · 8 tim terakhir</option><option value="all">Semua ronde · 32 tim</option><option value="a">Bagian A · 8 tim</option><option value="b">Bagian B · 8 tim</option><option value="c">Bagian C · 8 tim</option><option value="d">Bagian D · 8 tim</option></select></div><span class="small-copy muted">${icon('bracket')} Geser untuk menjelajah · Pilih match untuk detail</span></div><div id="full-bracket" class="bracket-scroll" tabindex="0" role="region" aria-label="Bracket turnamen yang dapat digeser">${boardHtml(state.bracketView)}</div><div class="bracket-legend"><span><i class="cyan"></i>Live / pemenang</span><span><i class="violet"></i>Pertandingan selesai</span><span><i></i>Terjadwal / belum ditentukan</span></div><div class="split section"><section class="panel panel-pad"><div class="eyebrow cream">PEREBUTAN TEMPAT KETIGA</div><p class="small-copy" style="margin:10px 0 18px">Mempertemukan kedua tim yang kalah di semifinal.</p>${matchHtml(matchData().third)}</section><section class="panel panel-pad"><h3>Bagaimana bracket ditetapkan?</h3><ul class="rule-list"><li><b>01</b><span>Peserta diverifikasi sebelum drawing.</span></li><li><b>02</b><span>Organizer meninjau seed dan bye, lalu mempublikasikan bracket resmi.</span></li><li><b>03</b><span>Tim yang menang maju berdasarkan hasil resmi.</span></li></ul></section></div>`)}
const players=[{name:'Volt',team:0,position:'Striker',goals:18,assists:7,saves:0,matches:5},{name:'Ignis',team:5,position:'Striker',goals:15,assists:6,saves:0,matches:2},{name:'Frost',team:2,position:'Striker',goals:12,assists:4,saves:0,matches:2},{name:'Aero',team:0,position:'Midfielder',goals:8,assists:14,saves:0,matches:5},{name:'Raven',team:1,position:'Striker',goals:8,assists:3,saves:0,matches:5},{name:'Ash',team:5,position:'Midfielder',goals:6,assists:11,saves:0,matches:2},{name:'Kai',team:3,position:'Midfielder',goals:5,assists:9,saves:0,matches:2},{name:'Rift',team:0,position:'Goalkeeper',goals:0,assists:2,saves:32,matches:5},{name:'Bastion',team:2,position:'Goalkeeper',goals:0,assists:1,saves:27,matches:2},{name:'Kaze',team:0,position:'Defender',goals:2,assists:5,saves:0,matches:5},{name:'Nox',team:0,position:'Defender',goals:1,assists:3,saves:0,matches:5},{name:'Ember',team:5,position:'Goalkeeper',goals:0,assists:2,saves:25,matches:2}];
function statPlayers(){return players.map((p,i)=>({...p,goals:p.goals+(state.phase==='finished'?[8,7,5,4,0,4,0,0,0,1,0,0][i]:0),assists:p.assists+(state.phase==='finished'?[4,3,2,6,0,4,0,1,1,2,1,1][i]:0),saves:p.saves+(state.phase==='finished'?[0,0,0,0,0,0,0,21,15,0,0,20][i]:0),matches:p.matches+(state.phase==='finished'?[7,9,8,7,0,9,0,7,8,7,7,9][i]:0)}))}
const metricNames={goals:'Gol',assists:'Assist',saves:'Save'};
function leaderboardPage(){const ready=['live','finished'].includes(state.phase);return eventShell(`<div class="page-heading"><div><div class="eyebrow cyan">THE PLAYMAKERS / MFL S3</div><h1>${state.phase==='finished'?'Nama yang meninggalkan jejak.':'Di balik setiap kemenangan.'}</h1><p>Statistik pemain dari pertandingan yang telah ditinjau dan diterbitkan organizer.</p></div>${ready?badge(state.phase==='finished'?'STATISTIK FINAL':'STATISTIK RESMI',state.phase==='finished'?'cream':'cyan'):''}</div>${ready?`<div class="section-head"><div class="segmented" role="group" aria-label="Peringkat berdasarkan statistik">${Object.entries(metricNames).map(([key,name])=>`<button data-metric="${key}" class="${key===state.metric?'active':''}" aria-pressed="${key===state.metric}">${name==='Gol'?'Top Scorer':name==='Assist'?'Top Assist':'Top Saves'}</button>`).join('')}</div><span class="small-copy muted">${state.phase==='finished'?'Final · 20 Sep, 22.15 WIB':'Update · 19 Sep, 19.10 WIB'}</span></div><div id="leaders"></div><div class="toolbar"><div class="field search-field"><label for="player-search">Cari pemain</label><input id="player-search" type="search" placeholder="Nickname atau nama tim…" value="${esc(state.query)}"></div><div class="field"><label for="player-position">Posisi</label><select id="player-position"><option value="all">Semua posisi</option><option>Striker</option><option>Midfielder</option><option>Defender</option><option>Goalkeeper</option></select></div><div class="field"><label for="player-team">Tim</label><select id="player-team"><option value="all">Semua tim</option>${[0,1,2,3,5].map(id=>`<option value="${id}">${teams[id].name}</option>`).join('')}</select></div></div><div id="player-results"></div><div class="notice" style="margin-top:22px"><b>${state.phase==='finished'?'Statistik akhir telah diterbitkan.':'Statistik North Force vs Borneo Kings belum masuk.'}</b><p>${state.phase==='finished'?'Peringkat menggunakan total statistik resmi event ini. Statistik yang belum dipublikasikan tidak ditampilkan.':'Series masih berlangsung. Gol, assist, dan save baru masuk ke peringkat setelah ditinjau organizer.'}</p></div><p class="info-note">Urutan: total ${metricNames[state.metric].toLowerCase()} tertinggi, jumlah game terbanyak, lalu nickname A–Z. Game = pertandingan individual dalam sebuah series. Daftar pada mockup ini adalah contoh pemain.</p>`:`<div class="empty-state">${icon('chart')}<div class="eyebrow violet" style="margin-bottom:12px">MENUNGGU PERTANDINGAN PERTAMA</div><h2>Setiap legenda dimulai dari nol.<br>Peringkatnya belum dimulai.</h2><p>Belum ada statistik resmi. Leaderboard akan terisi setelah organizer meninjau statistik pertandingan. Kenali dulu pemain dan tim yang akan bertanding.</p>${link('participants','Lihat tim peserta '+icon('arrow'),'button primary')}</div><div class="split section"><div class="panel panel-pad"><h3>Statistik yang akan tampil</h3><p class="small-copy" style="margin-top:12px">Gol, assist, save, dan jumlah game. Gunakan filter tim serta posisi untuk menemukan pemain favoritmu.</p></div><div class="panel panel-pad"><h3>Hanya statistik yang resmi</h3><p class="small-copy" style="margin-top:12px">Pemain tidak diberi ranking sementara sebelum pertandingan. Data yang masih menunggu review tidak masuk ke leaderboard.</p></div></div>`}`)}
function renderPlayers(){const sorted=statPlayers().sort((a,b)=>b[state.metric]-a[state.metric]||b.matches-a.matches||a.name.localeCompare(b.name));document.getElementById('leaders').innerHTML=`<div class="leaders">${sorted.slice(0,3).map((p,i)=>`<div class="leader"><span class="rank-watermark" aria-hidden="true">0${i+1}</span><div class="eyebrow ${i===0?'cream':'muted'}">${i===0?'LEADING THE BOARD':'RANK / 0'+(i+1)}</div><h3>${p.name}</h3><p>${teams[p.team].name} · ${p.position}</p>${crest(p.team)}<div class="leader-bottom"><div><strong class="${i===0?'cream':'cyan'}">${p[state.metric]}</strong> <span>${metricNames[state.metric]}</span></div><span>${p.matches} game</span></div></div>`).join('')}</div>`;const filtered=sorted.map((p,i)=>({...p,rank:i+1})).filter(p=>(p.name+' '+teams[p.team].name).toLowerCase().includes(state.query.toLowerCase())&&(state.position==='all'||p.position===state.position)&&(state.playerTeam==='all'||String(p.team)===state.playerTeam));document.getElementById('player-results').innerHTML=filtered.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Tabel statistik pemain"><table><thead><tr><th scope="col">RANK</th><th scope="col">PEMAIN</th><th scope="col">POSISI</th><th scope="col">GAME</th>${Object.entries(metricNames).map(([key,name])=>`<th scope="col" class="${key===state.metric?'metric-head':''}">${name.toUpperCase()} ${key===state.metric?'↓':''}</th>`).join('')}</tr></thead><tbody>${filtered.map(p=>`<tr><td class="table-rank ${p.rank===1?'cream':''}">${String(p.rank).padStart(2,'0')}</td><td><button class="table-person" style="background:none;border:0;padding:0;min-height:44px;text-align:left" data-team="${p.team}">${crest(p.team,'mini')}<span><b>${p.name}</b><small>${teams[p.team].name}</small></span></button></td><td class="muted">${p.position}</td><td>${p.matches}</td>${Object.keys(metricNames).map(key=>`<td class="${key===state.metric?'metric-cell':''}">${p[key]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="info-note">${filtered.length} pemain ditampilkan · Nomor rank tetap mengacu pada seluruh event</p>`:'<div class="empty-state"><h3>Pemain tidak ditemukan.</h3><p style="margin-top:10px">Ubah kata pencarian, tim, atau posisi.</p></div>';document.getElementById('player-position').value=state.position;document.getElementById('player-team').value=state.playerTeam}
function schedulePage(){const reg=state.phase==='registration';return eventShell(`<div class="page-heading"><div><div class="eyebrow cyan">MATCH DAY / MFL S3</div><h1>${reg?'Tandai kalendermu.':'Setiap match punya cerita.'}</h1><p>${reg?'Agenda event sudah tersedia. Pasangan tim dan jam per match diterbitkan bersama drawing resmi.':'Jadwal dan hasil series dalam satu tempat. Seluruh waktu menggunakan WIB (UTC+7).'}</p></div>${badge('18–20 SEP 2026','violet')}</div>${reg?`${scheduleTeaser()}<div class="notice" style="margin-top:22px"><b>Jadwal pertandingan menunggu drawing.</b><p>Bracket format dapat dilihat sekarang. Nama tim dan jadwal tiap pertandingan menyusul setelah dipublikasikan organizer.</p></div>`:`<div class="toolbar"><div class="field"><label for="schedule-round">Ronde</label><select id="schedule-round"><option value="all">Semua ronde</option><option value="r32">32 besar</option><option value="r16">16 besar</option><option value="qf">Quarterfinal</option><option value="sf">Semifinal</option><option value="final">Grand Final</option></select></div><span class="small-copy muted" style="padding-bottom:12px">${state.phase==='drawing'?'Jadwal resmi terbit 17 Sep, 20.00 WIB':'Perubahan jadwal langsung tercermin di daftar'}</span></div><div id="schedule-results"></div>`}`)}
function renderSchedule(){const d=matchData();const keys=state.scheduleFilter==='all'?['r32','r16','qf','sf','final']:[state.scheduleFilter];const shown=keys.flatMap(k=>d[k]);if(state.scheduleFilter==='all')shown.push(d.third);shown.sort((a,b)=>a.date.localeCompare(b.date));const days=[...new Set(shown.map(m=>m.date.split(' · ')[0]))];document.getElementById('schedule-results').innerHTML=days.map(day=>`<div class="schedule-day"><span>${day} 2026</span><span class="muted">WIB · Panggung utama</span></div><div class="schedule-list">${shown.filter(m=>m.date.startsWith(day)).map(m=>`<article class="fixture ${m.status==='live'?'current-match':''}"><div><b>${m.date.split(' · ')[1]}</b><p style="font-size:9px">WIB</p></div><small>${m.label}<br>Best of ${m.bo}</small><div class="fixture-team">${m.a===null?'':crest(m.a,'mini')}${m.a===null?'TBD':teams[m.a].name}</div><div class="fixture-score ${m.status==='live'?'cyan':''}">${m.sa===null?'vs':m.sa+' : '+m.sb}</div><div class="fixture-team">${m.b===null?'':crest(m.b,'mini')}${m.b===null?'TBD':teams[m.b].name}</div><button class="button" data-match="${m.id}">${m.status==='done'?'Hasil resmi':m.status==='live'?'● Live':'Detail'}</button></article>`).join('')}</div>`).join('');document.getElementById('schedule-round').value=state.scheduleFilter}
function showDialog(content){document.getElementById('dialog-body').innerHTML=content;if(!dialog.open)dialog.showModal()}
function showTeam(id){const t=teams[id];showDialog(`<div class="org-row">${crest(id)}<div><div class="eyebrow muted">TEAM PROFILE / ${t.city}</div><h2>${t.name}</h2></div></div>${badge(teamStatus(t).label,teamStatus(t).tone)}<p>Roster resmi untuk Miracle Football League S3.</p>${roster(t).map((p,i)=>`<div class="roster-row"><div><b>${p.name}</b>${p.captain?' <span class="badge violet">CAPTAIN</span>':''}</div><span>${p.role}</span></div>`).join('')}<div class="actions" style="margin-top:24px">${link('bracket','Lihat bracket '+icon('arrow'),'button primary')}${link('schedule','Jadwal event','button')}</div>`)}
function showMatch(id){const d=matchData();const m=[...d.r32,...d.r16,...d.qf,...d.sf,...d.final,d.third].find(x=>x.id===id);if(!m)return;if(state.phase==='registration'){showDialog(`<div class="eyebrow violet">PRATINJAU FORMAT</div><h2>${m.label}</h2><p>Slot TBD vs TBD · Best of ${m.bo}. Ini menunjukkan struktur kompetisi. Nama tim baru tampil setelah organizer mempublikasikan drawing resmi.</p><div class="notice"><b>Belum ada seed atau bye resmi.</b><p>Urutan pendaftaran tidak menentukan posisi tim.</p></div>`);return}showDialog(`<div class="eyebrow cyan">${m.label} / BEST OF ${m.bo}</div><h2>${m.a===null?'TBD':teams[m.a].name}<br><span class="muted">vs</span> ${m.b===null?'TBD':teams[m.b].name}</h2><p>${m.date} WIB · Panggung utama</p>${badge(m.status==='done'?'HASIL RESMI':m.status==='live'?'● SERIES BERLANGSUNG':'TERJADWAL',m.status==='done'?'violet':'cyan')}${m.sa!==null?`<div class="score" style="margin:23px 0">${m.sa} : ${m.sb}</div>`:''}<p>${m.status==='done'?'Skor series telah dikonfirmasi organizer. Pemenang melanjutkan ke ronde berikutnya sesuai bracket.':m.status==='live'?'Game 2 sedang berjalan. Skor di atas merupakan skor series. Statistik pemain menunggu review organizer.':m.a===null||m.b===null?'Peserta diisi setelah hasil ronde sebelumnya dikonfirmasi.':'Pasangan tim mengikuti drawing resmi yang dipublikasikan organizer.'}</p>${link('schedule','Buka jadwal & hasil '+icon('arrow'),'button')}`)}
function openInfo(kind){const infos={login:['Masuk ke Miracle','Pratinjau akses akun. Pada produk, captain masuk untuk mengelola tim dan organizer masuk ke workspace event.'],register:['Daftarkan tim ke MFL S3','Pratinjau alur: masuk atau buat akun → pilih tim dan lengkapi roster → bayar Rp20.000 → unggah bukti → tunggu verifikasi organizer.'],stream:['Siaran MFL Season 3','Area pemutar siaran akan menggunakan link resmi yang dikonfigurasi organizer. Mockup ini memakai data contoh dan tidak memutar siaran sungguhan.'],contact:['Hubungi Miracle League','Pada produk, kontak WhatsApp atau Instagram yang dikonfigurasi organizer tampil di sini. Mockup ini tidak mengirim pesan.'],archive:['MFL Season 2 · Arsip event','Event terdahulu tersedia sebagai recap pada URL permanennya. Rangkaian mockup ini berfokus pada event utama MFL S3.'],certificate:['Champion · Garuda Nova','Pratinjau sertifikat: MFL Season 3 · Champion · Garuda Nova · Diterbitkan 20 September 2026. Pada produk, sertifikat diterbitkan organizer dan memiliki halaman verifikasi.']};if(kind==='share'){showDialog(`<h2>Bagikan event.</h2><p>Salin tautan halaman mockup ini. Fase yang dipilih ikut tersimpan agar orang lain melihat konteks yang sama.</p><div class="field"><label for="share-link">Tautan mockup</label><input id="share-link" readonly value="${esc(location.href)}"></div><button class="button primary" style="margin-top:16px" data-copy>Salin tautan ${icon('share')}</button>`);return}const info=infos[kind];if(info)showDialog(`<div class="eyebrow violet">PRATINJAU INTERAKSI</div><h2>${info[0]}</h2><p>${info[1]}</p>${kind==='certificate'?`<div class="certificate-mini">${icon('trophy')}<div><div class="eyebrow cream">MIRACLE FOOTBALL LEAGUE S3</div><h2 style="color:var(--cream)">CHAMPION</h2><h3>GARUDA NOVA</h3></div></div>`:kind==='register'?'<div class="notice"><b>Data ini tidak dikirim.</b><p>Pendaftaran dan pembayaran asli tetap mengikuti alur captain yang sudah tersedia.</p></div>':''}`)}
function updateLinks(){document.querySelectorAll('[data-page]').forEach(a=>{if(a.tagName==='A')a.href=href(a.dataset.page)});document.querySelectorAll('.global-nav a').forEach(a=>{const active=a.dataset.page==='home'?state.page==='home':state.page!=='home';a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelectorAll('[data-phase]').forEach(b=>{const active=b.dataset.phase===state.phase;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
function render(){root.innerHTML=({home:homepage,event:eventPage,participants:participantsPage,bracket:bracketPage,leaderboard:leaderboardPage,schedule:schedulePage,events:eventsPage}[state.page])();if(state.page==='home'){const target=root.querySelector('.section.two-col');if(target)target.insertAdjacentHTML('beforebegin',otherEventSection());const num=target?.querySelector('.section-number');if(num)num.textContent='03';root.querySelector('.history-strip')?.remove()}if(state.page==='events')renderEvents();if(state.page==='participants')renderTeams();if(state.page==='leaderboard'&&['live','finished'].includes(state.phase))renderPlayers();if(state.page==='schedule'&&state.phase!=='registration')renderSchedule();if(state.page==='bracket')document.getElementById('bracket-stage').value=state.bracketView;updateLinks();correctGlobalNav();requestAnimationFrame(drawConnectors);document.title=`${pageNames[state.page]} · MFL S3 · Miracle V3 Mockup`}
function correctGlobalNav(){document.querySelectorAll('.global-nav a').forEach(a=>{const active=a.dataset.page==='home'?state.page==='home':a.dataset.page==='events'?state.page==='events':!['home','events'].includes(state.page);a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
function readRoute(){const [page,phase]=location.hash.slice(1).split('/');state.page=pageNames[page]?page:'home';state.phase=phases[phase]?phase:'live';state.query='';state.teamStatus='all';state.teamPage=1;state.position='all';state.playerTeam='all';state.scheduleFilter=state.phase==='drawing'?'r32':state.phase==='finished'?'final':'qf';render()}
document.addEventListener('click',async event=>{const page=event.target.closest('[data-page]');if(page){event.preventDefault();if(dialog.open)dialog.close();const next=href(page.dataset.page);if(location.hash===next){window.scrollTo(0,0);return}location.hash=next;return}const phase=event.target.closest('[data-phase]');if(phase){location.hash=`${state.page}/${phase.dataset.phase}`;return}const team=event.target.closest('[data-team]');if(team){showTeam(Number(team.dataset.team));return}const match=event.target.closest('[data-match]');if(match){showMatch(match.dataset.match);return}const info=event.target.closest('[data-dialog]');if(info){openInfo(info.dataset.dialog);return}const pagination=event.target.closest('[data-team-page]');if(pagination){state.teamPage=Number(pagination.dataset.teamPage);renderTeams();document.getElementById('team-results').scrollIntoView({block:'start'});return}const metric=event.target.closest('[data-metric]');if(metric){state.metric=metric.dataset.metric;render();return}if(event.target.closest('[data-copy]')){try{await navigator.clipboard.writeText(location.href);toast('Tautan mockup disalin.')}catch{document.getElementById('share-link').select();toast('Tautan dipilih. Gunakan Ctrl+C untuk menyalin.')}}});
document.addEventListener('click',event=>{const award=event.target.closest('[data-award-certificate]');if(award){showAwardCertificate(award.dataset.awardCertificate);return}const filter=event.target.closest('[data-event-filter]');if(filter){state.eventFilter=filter.dataset.eventFilter;render();return}const card=event.target.closest('[data-other-event]');if(card)showOtherEvent(card.dataset.otherEvent)});
document.addEventListener('input',event=>{if(event.target.id==='team-search'){state.query=event.target.value;state.teamPage=1;renderTeams()}if(event.target.id==='player-search'){state.query=event.target.value;renderPlayers()}});
document.addEventListener('change',event=>{const id=event.target.id,v=event.target.value;if(id==='team-status'){state.teamStatus=v;state.teamPage=1;renderTeams()}if(id==='player-position'){state.position=v;renderPlayers()}if(id==='player-team'){state.playerTeam=v;renderPlayers()}if(id==='bracket-stage'){state.bracketView=v;document.getElementById('full-bracket').innerHTML=boardHtml(v);drawConnectors()}if(id==='schedule-round'){state.scheduleFilter=v;renderSchedule()}});
let toastTimer;function toast(text){const el=document.querySelector('.toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});
window.addEventListener('hashchange',()=>{readRoute();window.scrollTo(0,0);root.focus({preventScroll:true})});window.addEventListener('resize',drawConnectors);document.fonts.ready.then(drawConnectors);readRoute();
